@Configuration
public class AmqpToKafkaIntegrationConfig {

    @Bean
    public IntegrationFlow amqpToKafkaFlow(AmqpInboundChannelAdapterSpec amqpInbound,
                                           KafkaProducerMessageHandler<String, String> kafkaHandler) {
        return IntegrationFlow
            .from(amqpInbound)
            .transform(new PayloadSerializingTransformer())
            .enrichHeaders(s -> s.headerFunction("kafka_key", m -> m.getHeaders().get("amqp_messageId")))
            .handle(kafkaHandler)
            .get();
    }
}
